import { AppBar, Toolbar, Typography, Button, Box } from '@mui/material';
import { Link } from 'react-router-dom';

const Navbar = () => {
  return (
    <AppBar
      position="static"
      sx={{
        background: 'linear-gradient(135deg, #1e3c72 0%, #2a5298 100%)',
        boxShadow: '0 4px 12px rgba(0, 0, 0, 0.1)',
      }}
    >
      <Toolbar sx={{ display: 'flex', justifyContent: 'space-between' }}>
        <Typography
          variant="h6"
          component="div"
          sx={{
            flexGrow: 1,
            fontWeight: 'bold',
            letterSpacing: '1.2px',
            textTransform: 'uppercase',
            color: '#fff',
            fontFamily: 'Poppins, sans-serif',
          }}
        >
          Income & Expense Manager
        </Typography>
        <Box sx={{ display: 'flex', gap: 2 }}>
          <Button
            color="inherit"
            component={Link}
            to="/"
            sx={{
              fontSize: '16px',
              fontWeight: '500',
              textTransform: 'capitalize',
              padding: '8px 16px',
              transition: 'all 0.3s',
              borderRadius: '8px',
              '&:hover': {
                backgroundColor: 'rgba(255, 255, 255, 0.2)',
              },
            }}
          >
            Dashboard
          </Button>
          <Button
            color="inherit"
            component={Link}
            to="/stock"
            sx={{
              fontSize: '16px',
              fontWeight: '500',
              textTransform: 'capitalize',
              padding: '8px 16px',
              transition: 'all 0.3s',
              borderRadius: '8px',
              '&:hover': {
                backgroundColor: 'rgba(255, 255, 255, 0.2)',
              },
            }}
          >
            Stock
          </Button>
          <Button
            color="inherit"
            component={Link}
            to="/finance"
            sx={{
              fontSize: '16px',
              fontWeight: '500',
              textTransform: 'capitalize',
              padding: '8px 16px',
              transition: 'all 0.3s',
              borderRadius: '8px',
              '&:hover': {
                backgroundColor: 'rgba(255, 255, 255, 0.2)',
              },
            }}
          >
            Finance
          </Button>
          <Button
            color="inherit"
            component={Link}
            to="/invoice"
            sx={{
              fontSize: '16px',
              fontWeight: '500',
              textTransform: 'capitalize',
              padding: '8px 16px',
              transition: 'all 0.3s',
              borderRadius: '8px',
              '&:hover': {
                backgroundColor: 'rgba(255, 255, 255, 0.2)',
              },
            }}
          >
            Invoices
          </Button>
        </Box>
      </Toolbar>
    </AppBar>
  );
};

export default Navbar;
